import { GENERIC_EXCEPTION_DISPLAY_MESSAGES } from './constants';
import { Locale } from './locale';

export abstract class BaseException<T = any> extends Error {
    public name: string;

    public data?: T | any;

    public innerException: BaseException | undefined;

    public buttonText: string;

    public displayMessage: string;

    public ignorable: boolean = false;

    constructor(name: string, message: string, data: T = {} as T, stack?: string) {
        super(message);
        this.data = data;
        this.name = name;

        if (stack) {
            this.stack = stack;
        } else {
            // if a stack doesn't exist then we throw an error to grab the stack
            // looking at you PhantomJS... ಠ益ಠ
            if (!this.stack) {
                try {
                    throw new Error();
                } catch (e: any) {
                    this.stack = e.stack;
                }
            }

            const stackFrames = this.stack ? this.stack.split('\n') : [];
            stackFrames.splice(0, 3);
            stackFrames.unshift(`Unhandled ${this.name}: ${this.message}`);
            this.stack = stackFrames.join('\n');
        }

        // Fix the prototype chain.
        // This is required as the Error constructor returns a new 'this' instance
        // which is not the object being constructed. Why? Because Javascript...
        Object.setPrototypeOf(this, new.target.prototype);
    }

    public abstract localise(locale: Locale): void;

    protected getGenericErrorMessage(locale: Locale) {
        return GENERIC_EXCEPTION_DISPLAY_MESSAGES[locale].GENERIC_ERROR_MESSAGE;
    }

    protected getGenericNetworkErrorMessage(locale: Locale) {
        return GENERIC_EXCEPTION_DISPLAY_MESSAGES[locale].GENERIC_NETWORK_MESSAGE;
    }

    protected getButtonText(locale: Locale) {
        return GENERIC_EXCEPTION_DISPLAY_MESSAGES[locale].RECONNECT;
    }
}